#[tokio::test]
async fn baseline_recovery_has_no_lifetime_budget() {
let fixture=fixture(Wire::Chat).await;
fixture.proxy.health.fail("fixture@first",503,"fixture outage",Wire::Chat,&request()).await;
for _ in 0..6 { fixture.proxy.health.data.write().await.incidents.get_mut("fixture@first").unwrap().retry_at=0; fixture.proxy.heal_once().await; }
let calls=fixture.calls.lock().unwrap().len();assert!(calls<=3,"one incident performed {calls} recovery calls without a finite lifetime budget");
}
